select B.GROUP_ID as id,B.NAME as label from PUBLIC_GROUP B
LEFT JOIN SYS_ROLE sr ON B.ROLE_ID=sr.ROLE_ID
where 1=1
AND  sr.APP_ID = #{appId}

    AND sr.ROLETYPE_ID = #{roletypeId}

AND  B.IS_DISABLED = 0

select sp.POSITION_ID as id,sp.NAME AS label from PUBLIC_GROUP_POSITION B LEFT JOIN SYS_POSITION sp ON sp.POSITION_ID=B.POSITION_ID LEFT JOIN PUBLIC_GROUP G ON B.GROUP_ID = G.GROUP_ID LEFT JOIN SYS_ROLE sr ON G.ROLE_ID=sr.ROLE_ID where 1=1
AND sr.ROLETYPE_ID = #{roletypeId}
AND B.GROUP_ID = #{groupId}
AND sp.DEL_FLAG=0 ORDER BY sp.PRIORITY asc

SELECT  sp.POSITION_ID as id,sp.PARENT_ID,sp.NAME,sp.POS_RANK,sp.CREATE_TIME,sp.PRIORITY
, SR.NAME as roletypeName,pgP.GROUP_ID as groupId
FROM SYS_ROLE_POSITION B
LEFT JOIN SYS_POSITION sp ON B.POSITION_ID = sp.POSITION_ID
LEFT JOIN CORE_ROLETYPE SR ON sp.ROLETYPE_ID = SR.ROLETYPE_ID
left join PUBLIC_GROUP_POSITION pgP on pgP.POSITION_ID = B.POSITION_ID
where 1=1

    AND sp.NAME like  concat('%', #{name},'%')


    AND sp.POS_RANK = #{posRank}


    AND sp.ROLETYPE_ID = #{roletypeId}


    AND sp.CREATE_TIME like  concat('%', #{createTime},'%')


    and  B.ROLE_ID=#{parentId}


     AND date_format(B.CREATE_TIME,'%Y-%m-%d') >= #{startTime}
    AND date_format(B.CREATE_TIME,'%Y-%m-%d') <= #{endTime} 

ORDER BY PRIORITY ASC

SELECT B.POSITION_ID as id,B.PARENT_ID,B.NAME,B.POS_RANK,B.ROLETYPE_ID,B.CREATE_TIME,B.PRIORITY
, SR.NAME as roletypeName,pgP.GROUP_ID as groupId,B.CODE AS wlType
FROM
SYS_POSITION B
left join CORE_ROLETYPE SR on B.ROLETYPE_ID = SR.ROLETYPE_ID
left join PUBLIC_GROUP_POSITION pgP on pgP.POSITION_ID = B.POSITION_ID
where 1 = 1

    AND B.NAME like  concat('%', #{name},'%')


    AND B.POS_RANK = #{posRank}


    AND B.ROLETYPE_ID = #{roletypeId}


    AND B.CREATE_TIME like  concat('%', #{createTime},'%')


    and  B.PARENT_ID=#{parentId}


     AND date_format(B.CREATE_TIME,'%Y-%m-%d') >= #{startTime}
    AND date_format(B.CREATE_TIME,'%Y-%m-%d') <= #{endTime} 

ORDER BY PRIORITY ASC

SELECT B.GROUP_ID as id,B.NAME,B.IS_DISABLED,B.PRIORITY ,SR.NAME as roleTypeName,sr.NAME as roleName FROM PUBLIC_GROUP B LEFT JOIN SYS_ROLE sr ON B.ROLE_ID = sr.ROLE_ID LEFT JOIN CORE_ROLETYPE SR ON sr.ROLETYPE_ID = SR.ROLETYPE_ID where 1=1
AND B.NAME like concat('%', #{name},'%')
AND B.IS_DISABLED = #{isDisabled}
AND SR.ROLETYPE_ID = #{roletypeId}
AND sr.ROLE_ID = #{roleId}
ORDER BY PRIORITY ASC

